INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66244966', 66244966, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Ahli Manajemen Anggaran dan Akuntabilitas Keuangan Kegiatan Penyusunan Dokumen Teknis Kota Balikpapan dan Kota Palembang dalam rangka Global Environment Facility Sustainable Cities Impact Project (GEF-SCIP) di Lingkungan Kerja Direktorat Konektivitas dan Infrastruktur Logistik, Kedeputian Bidang Infrastruktur', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 96000000, 'December 2025', 'APBN - HIBAH LUAR NEGERI (I)', 0, 1, '12', '1. mendukung tim proyek dalam menyusun Rencana Kerja. Menyusun Rencana Pengadaan proyek berdasarkan Rencana Kerja; 2. menyusun proyeksi keuangan tiap kuartal dalam koordinasi dengan tim proyek dan PMU (Unit Manajemen Proyek); 3. membantu tim proyek untuk memastikan ketersediaan anggaran pada DIPA dan memfasilitasi revisi DIPA tepat waktu mengacu ke rencana kerja proyek; 4. menyiapkan dan memproses data untuk Interim Financial Report (IFR) berdasarkan panduan dari PMU; 5. memastikan seluruh dokumen pertanggungjawaban memenuhi persyaratan (Sesuai KAK)', 'a. Pendidikan perguruan tinggi negeri minimal S-1 bidang Administrasi, Manajemen, Ekonomi, Akuntansi, Sekretari, atau bidang lain yang relevan; b. Memiliki pengalaman kerja bidang Administrasi Keuangan pemerintah, donor, atau lembaga nasional ataupun internasional minimal 1 tahun; c. Memiliki pengalaman bekerja dalam sektor pemerintahan minimal 1 tahun (melampirkan bukti referensi/kontrak kerja/bukti contoh hasil tulisan); d. Memahami sistem penganggaran dan pelaporan proyek pemerintah (termasuk DIPA dan mekanisme revisinya); e. Memiliki pengalaman dalam mengikuti workshop, training atau sejenis (melampirkan bukti referensi/sertifikat); f. Memiliki pengalaman organisasi yang memadai; g. Memiliki kemampuan menulis laporan serta membuat presentasi (melampirkan bukti referensi/kontrak kerja/bukti contoh hasil tulisan).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2612241);
