INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66210693', 66210693, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Pemeliharaan Perangkat Pompa Air DJKI Tangerang pada Direktorat Jenderal Kekayaan Intelektual - Provinsi DK Jakarta TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 199883333, 'February 2026', 'APBN - PNBP (D)', 1, 1, '10 Bulan', 'Fasilitas gedung yang harus dipelihara agar seluruh kegiatan di dalamnya dapat berlangsung dengan baik. Salah satunya adalah perangkat penyedot air berupa pompa. DJKI memiliki fasilitas pompa untuk gedung di Tangerang untuk sistem pengolahan air bersih. Pompa air bersih merupakan salah satu komponen vital dalam sistem utilitas gedung yang berfungsi untuk menjamin ketersediaan air bersih bagi seluruh pengguna gedung. Seiring waktu dan pemakaian yang intensif, kinerja pompa dapat menurun akibat ausnya komponen mekanik, penurunan efisiensi motor, kebocoran pipa, serta gangguan pada panel kontrol. Untuk menjaga agar sistem distribusi air tetap berfungsi optimal, perlu dilakukan kegiatan pemeliharaan rutin dan berkala sesuai standar operasional dan rekomendasi pabrikan. Dengan demikian, perlu diadakan kegiatan tersendiri berupa Pemeliharaan Perangkat Pompa Air.Melalui kegiatan ini akan diadakan suku cadang perangkat pompa yang ada di gedung DJKI, baik yang di Tangerang. Model pengadaannya adalah menunjuk satu penyedia untuk melakukan pemeliharaan tersebut.', 'Pemeliharaan Perangkat Pompa Air 1 Unit', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2614186);
