INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66250294', 66250294, 'analyze_legacy', 'Kab. Paser', 'kabkota', 'Dinas Pemadam Kebakaran', 'Helper Petugas Operasional Lapangan (Pemadam Kebakaran) 62', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Paser (Kab.)', 28600000, 'March 2026', 'APBD', 1, 1, '11 Bulan', 'Melaksanakan pekerjaan teknis, mempersiapkan alat dan bahan, mengikuti instruksi dari teknisi, operator, atasan atau ahli lainnya ; Memindahkan, menyiapkan dan mengangkat peralatan evakuasi ; Memastikan kelancaran operasional, melakukan pemeriksaan barang, memastikan semua peralatan Evakuasi siap digunakan. seperti kegiatan evakuasi hewan liar, mobil terperosok, pintu terkunci, barang terjatuh ke dalam parit, Evakuasi Cincin dan lainnya yang tersangkut di anggota tubuh dan jenis evakuasi lainnya ; Melaksanakan distribusi logistik dan peralatan ringan ke pos sektor atau lokasi kegiatan operasional sesuai dengan kebutuhan lapangan ; Melakukan Penyemprotan jalan, tempat ibadah, Saluran pembuangan dan Parit Buntu serta distribusi air bersih ke Masyarakat yang membutuhkan ; Membantu Masyarakat Korban Kebakaran untuk mengamankan Jiwa dan harta benda pada saat terjadi kebakaran; Melaksanakan Penanganan pohon tumbang, Pembersihan jalan pasca laka lantas, Oli, CPO dan Solar tumpah di Jalan umum.', 'SLTA Sederajat ; Membutuhkan Sertifikasi Damkar 1 atau Sertifikat K3', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2615350);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66249085', 66249085, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Belanja Makanan dan Minuman Kegiatan Rekonstruksi Sejarah', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Barat (Kota)', 53192000, 'June 2026', 'APBD', 1, 1, '260 Orang', 'Pekerjaan ini meliputi penyediaan konsumsi berupa nasi box, snack, dan prasmanan untuk mendukung pelaksanaan Kegiatan Rekonstruksi Sejarah, yang mencakup pengadaan, pengolahan, pengemasan, dan penyajian makanan dan minuman sesuai jumlah dan jadwal kegiatan, dengan memperhatikan standar kebersihan, kesehatan, mutu makanan, serta ketepatan waktu penyajian bagi panitia, narasumber, dan tamu undangan.', 'Nasi Box (Nasi, Lauk, Sayur, Kerupuk, Buah dan Air Mineral) Kualitas: Makanan segar, bersih, dan sesuai standar konsumsi Snack (tiga jenis snack dan Air Mineral) Prasmanan disajikan dalam kondisi higienis dan layak konsumsi, terdiri atas nasi, lauk pauk, sayuran, pelengkap (sambal dan kerupuk), buah segar, serta air mineral. Penyajian dilakukan secara prasmanan menggunakan peralatan saji yang bersih dan tertata rapi, dengan memperhatikan standar kebersihan, kesehatan, dan ketepatan waktu sesuai jadwal kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2615351);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66212033', 66212033, 'analyze_legacy', 'Kab. Ngada', 'kabkota', 'BADAN PERENCANAAN PEMBANGUNAN, RISET DAN INOVASI DAERAH', 'Tiket Pesawat Perjalanan Dinas Dalam Negeri Pergi Pulang bagi Kepala Daerah/Pimpinan DPRD, Sekretaris Daerah dan Anggota DPRD, Eselon IIB, Eselon III/Golongan IV, Eselon IV/Golongan III, II, I', 'Jasa Lainnya', 'Dikecualikan', 'Nusa Tenggara Timur, Ngada (Kab.)', 11600000, 'January 2026', 'APBD', 0, 1, '1 Orang x 2 Kali', 'Biaya Taxi bagi Kepala Daerah/Pimpinan DPRD, Sekretaris Daerah dan Anggota DPRD, Eselon IIB, Eselon III/Golongan IV, Eselon IV/Golongan III, II, I; Biaya Penginapan Perjalanan Dinas Dalam Negeri bagi Eselon III/Golongan IV; Tiket Pesawat Perjalanan Dinas Dalam Provinsi NTT Pergi Pulang Bagi Kepala Daerah/Pimpinan DPRD, Sekretaris Daerah dan Anggota DPRD, Eselon IIB, Eselon III/Golongan IV, Eselon IV/Golongan III, II, I; Biaya Taxi bagi Kepala Daerah/Pimpinan DPRD, Sekretaris Daerah dan Anggota DPRD, Eselon IIB, Eselon III/Golongan IV, Eselon IV/Golongan III, II, I; Tiket Pesawat Perjalanan Dinas Dalam Negeri Pergi Pulang bagi Kepala Daerah/Pimpinan DPRD, Sekretaris Daerah dan Anggota DPRD, Eselon IIB, Eselon III/Golongan IV, Eselon IV/Golongan III, II, I;', 'Bajawa-DKI Jakarta;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2615352);
