INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66254324', 66254324, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN LALU LINTAS DAN PENINGKATAN ANGKUTAN KERETA API', 'Pengembangan SDM Terkait Supply Chain And Logistic Management of Railways', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Pusat (Kota)', 1000000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Ruang lingkup pekerjaan ini, meliputi: 1) Melakukan koordinasi dengan pemberi kerja guna menyamakan persepsi terkait kebutuhan dan ketersediaan materi yang akan disampaikan dalam kegiatan Pengembangan SDM Bidang Supply Chain and Logistics Management of Railways dan Kesepakatan/Perjanjian Kontrak dalam penyelenggaraan peningkatan kompetensi SDM. 2) Menyediakan pelatihan yang dibutuhkan dari unit organisasi khususnya dalam hal Pengembangan SDM Bidang Supply Chain and Logistics Management of Railways; 3) Menyediakan pelaksanaan penyelenggaraan Pengembangan SDM Bidang Supply Chain and Logistics Management of Railways; 4) Melaksanakan Peningkatan Kompetensi SDM dengan pendampingan oleh panitia sesuai jadwal yang telah disepakati oleh panitia dan membantu dalam menyediakan pengakomodasian dan pendukung pelaksanaan diklat; 5) Materi diklat Pengembangan SDM Bidang Supply Chain and Logistics Management of Railways diantaranya: a) Pemahaman konsep dasar supply chain dan pengelolaannya pada angkutan multimoda dengan kereta api; b) Pemahaman konsep pemenuhan Customer Accomodation dalam proses angkutan barang; c) Pemanfaatan teknologi informasi dan digitalisasi dalam optimasi angkutan multimoda dengan kereta api; d) Best practices dalam manajemen logistik perkeretaapian dari berbagai negara; e) Studi kasus dan simulasi penerapan strategi supply chain dan logistik di sektor perkeretaapian. 6) Penyusunan laporan sekurang-kurangnya meliputi waktu pelaksanaan, tempat pelaksanaan, jumlah peserta, bahan ajar, dan dokumentasi saat pelaksanaan kegiatan.', 'Sesuai dengan KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2618516);
