INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66253181', 66253181, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN LALU LINTAS DAN PENINGKATAN ANGKUTAN KERETA API', 'Studi Pengembangan Fasilitas dan Infrastruktur Logistik Berbasis KA di Pulau Jawa', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1200000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Ruang Lingkup Kegiatan: 1) Menyusun Timeline dan rencana kerja Studi Pengembangan Fasilitas Dan Infrastruktur Logistik Berbasis KA Di Pulau Jawa; 2) Melakukan koordinasi yang intensif dengan Direktorat Jenderal Perkeretaapian maupun stakeholder terkait lainnya dalam pelaksanaan kegiatan ini; 3) Melakukan pengumpulan data sekunder, termasuk menginventarisasi dan mereviu studi-studi yang terdahulu terkait Studi Pengembangan Fasilitas Dan Infrastruktur Logistik Berbasis KA di Pulau Jawa; 4) Pelaksanaan survei lapangan dan wawancara stakeholder terkait guna menginventarisasi dan mengidentifikasi fasilitas dan infrastruktur layanan angkutan barang KA di Pulau Jawa, termasuk kondisi dan lokasi tempat bongkar/muat, kapasitas, tingkat utilisasi, kondisi fasilitas peralatan bongkar/muat, dan konektivitas atau aksesibilitas antar moda; 5) Melakukan analisis kinerja dan permasalahan yang ditemukan berdasarkan hasil survei; 6) Menyusun buku profil yang berisikan kondisi eksisting fasilitas logistik layanan angkutan barang KA di Pulau Jawa; 7) Melakukan Benchmarking dengan mengkaji Standar Teknis dan operasional yang berlaku di negara lain, dan memberikan rekomendasi penerapan di Indonesia; 8) Pelaksanaan Focus Group Discussion (FGD) guna memperoleh masukan dari operator KA barang, pengguna jasa angkutan barang, asosiasi logistik, dan pihak terkait lainnya; 9) Memformulasikan hasil yang diperoleh dari Studi Pengembangan Fasilitas dan Infrastruktur Logistik Berbasis KA di Pulau Jawa, berupa rekomendasi kebijakan pengembangan fasilitas logistik, prioritas lokasi, tahapan implementasi, dan simulasi kebutuhan investasi.', 'Sesuai Dengan KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2618753);
