INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66215126', 66215126, 'analyze_legacy', 'Kementerian Hukum', 'central', '02 KANWIL JAWA BARAT SETJEN', 'Pengadaan/Pembayaran Tunjangan Hari Raya (THR) Tenaga Outsourcing pada Kantor Wilayah Kementerian Hukum Jawa Barat Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 127500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Sebagai bentuk pemenuhan hak normatif pekerja untuk menunjang kebutuhan menyambut Hari Raya Keagamaan, meningkatkan kesejahteraan, serta loyalitas. Ini wajib dibayarkan perusahaan alih daya (vendor) untuk memastikan kepatuhan terhadap aturan ketenagakerjaan.', '1. Berdasarkan Peraturan Menteri Ketenagakerjaan No 6 Tahun 2016, pekerja outsourcing berhak menerima THR, asalkan masa kerja telah mencapai 1 bulan atau lebih; 2. Membantu pekerja outsourcing memenuhi kebutuhan ekonomi ekstra menjelang hari raya; 3. Sebagai bentuk apresiasi atas kontribusi kerja yang dapat meningkatkan motivasi dan loyalitas tenaga outsourcing.', 127500000, 'high', 'THR bagi tenaga outsourcing merupakan hak normatif pekerja yang pada prinsipnya menjadi kewajiban perusahaan penyedia jasa, sebagaimana juga tercermin dalam uraian spesifikasi. Pengadaan dengan APBN untuk membayarkan kewajiban vendor berindikasi mengalihkan beban biaya swasta ke anggaran negara dan berpotensi tidak tepat penggunaan dananya.', NULL, NULL, 3, 1, 1, 1, 1, 2619070);
