INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66253825', 66253825, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual Penyusunan Kajian Analisis Komparatif Perencanaan Pembangunan Berbasis Pendekatan Adaptif Kegiatan Koordinasi Penyusunan Rencana Kerja Pemerintah (Rkp) Tahun 2027 Direktorat Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99990000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', '1. Menyusun kerangka kerja pelaksanaan kegiatan, termasuk instrumen, jadwal, dan mekanisme pelaksanaannya; 2. Melakukan penyelarasan kebijakan efisiensi anggaran terhadap desain harmonisasi hubungan pusat dan daerah; 3. Melakukan pemetaan keselarasan dukungan kegiatan terhadap pelaksanaan Prioritas Nasional lintas sektor; 4. Melakukan penyusunan analisis kesenjangan antar level dokumen perencanaan menggunakan pendekatan adaptif; 5. Melakukan penyusunan prognosis target perencanaan berdasarkan gap analisis; 6. Melakukan forward estimate anggaran berdasarkan prognosis target yang sudah disusun 7. Menyusun laporan akhir analisis komparatif perencanaan pembangunan berbasis pendekatan adaptif,', '1. Merupakan Konsultansi dalam negeri (dibuktikan dengan identitas kewarganegaraan seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal Strata Satu (S-1) di bidang Perencanaan Wilayah dan Kota/Planologi/Ilmu pemerintahan/Administrasi Negara, yang dibuktikan dengan ijazah; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak; 5. Memiliki pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan), di bidang perencanaan dan/atau evaluasi kebijakan pemerintah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2619270);
