INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66253767', 66253767, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN LALU LINTAS DAN PENINGKATAN ANGKUTAN KERETA API', 'Studi Ability To Pay (ATP) Willingness To Pay (WTP) Angkutan Orang Dengan Ka Antarkota di Pulau Jawa', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1300000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Ruang Lingkup Kegiatan : 1) Persiapan, dengan melakukan pengumpulan data sekunder Data Ability to pay (ATP) dan Willingness to pay (WTP) Antarkota di Pulau Jawa Tahun sebelumnya, studi - studi terdahulu yang berkaitan dengan Ability to pay (ATP) dan Willingness to pay (WTP) dan pembuatan kuesioner untuk penumpang kereta api kelas ekonomi dengan menentukan jumlah responden sesuai dengan rumus Ilmu Statistik sehingga menggambarkan jumlah responden yang mewakili populasi di wilayah studi; 2) Kegiatan lapangan, pengumpulan data primer melalui survai permintaan perjalanan untuk mengetahui perkiraan jumlah penumpang dan survey/wawancara kepada penumpang kereta api kelas ekonomi dengan panduan daftar pertanyaan yang ada di kuisioner, baik di stasiun maupun di perjalanan kereta api dilakukan terhadap penumpang KA Ekonomi PSO Jarak Jauh, KA Jarak Sedang (KA Antarkota); 3) Melakukan analisis ATP - WTP KA-KA Antarkota di Pulau Jawa dari data hasil survai dan kondisi ekonomi masyarakat pengguna layanan kereta api kelas ekonomi. Hasil dari analisis ini digambarkan dalam kurva ATP dengan range biaya perjalanan yang mampu dibayar pengguna kereta api kelas ekonomi, dan persamaan WTP yang menggambarkan sensivitas pengguna kereta api kelas ekonomi akan perubahan tarif; 4) Menyusun laporan hasil analisis ATP - WTP angkutan orang dengan kereta api antarkota kelas ekonomi PSO di Pulau Jawa, termasuk memberikan rekomendasi atas tarif parsial pemerintah yang tepat diberlakukan pada KA-KA Ekonomi PSO Antarkota di Pulau Jawa; 5) Menyusun perkiraan jumlah penumpang kereta api kelas ekonomi PSO khususnya kereta api Antarkota di Pulau Jawa pada semua lintas pelayanan selama 5 Tahun (2026 s/d 2029); 6) Menyusun rekomendasi terkait Ability to Pay (ATP) - Willingness to Pay (WTP) penumpang KA kelas Ekonomi PSO (khususnya KA Antarkota) untuk bahan masukan dalam rangka kebijakan pemerintah terkait penetapan tarif KA kereta api antarkota kelas ekonomi PSO di Pulau Jawa dari Tahun 2026 s/d 2029.', 'Sesuai dengan KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2619715);
