INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66253472', 66253472, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Senior Urban Specialist Untuk Pengembangan Desain Besar Manajemen Pengetahuan  Kegiatan Global Environment Facility Indonesia Sustainable Cities Impact Project (GEF INDONESIA SCIP)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 52350000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', '1. Memberikan dukungan keahlian dalam menyusun desain besar manajemen pengetahuan untuk kegiatan GEF Indonesia SCIP; 2. Membantu mengoordinasikan dan memberikan dukungan teknis dalam perencanaan, persiapan, dan implementasi kegiatan GEF Indonesia SCIP Komponen 4; 3. Membantu mengoordinasikan pelaksanaan kegiatan Komponen 4 bersama dengan seluruh PIU dalam lingkup kegiatan GEF Indonesia SCIP, Bank Dunia, Tim Konsultan, dan Pemerintah Daerah terlibat; 4. Membantu mengoordinasikan penyusunan KAK dan RAB pada aktivitas yang akan diselenggarakan dalam pelaksanaan kegiatan GEF Indonesia SCIP Komponen 4; 5. Membantu memfasilitasi pelaksanaan kegiatan peningkatan kapasitas, dialog kebijakan, dan pertukaran pengetahuan yang dilaksanakan dalam lingkup kegiatan Komponen 4 GEF Indonesia SCIP;', '1. Merupakan Jasa Konsultan Individual dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki Pendidikan minimal S2 Perencanaan Wilayah dan Kota (dibuktikan dengan ijazah); 4. Memiliki pengalaman kerja minimal 7 (tujuh) tahun di bidang perencanaan pembangunan atau perkotaan (dibuktikan dengan surat referensi/kontrak); 5. Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 3 (satu) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2619902);
